    // DNS 窗口在板子忙时和空闲时会得出不同结论，SR 系列约束
    // （同源纪律、证据可复现）与单元测试可判定性会同时失效。
    //
    // 所以分两层：decide() 给出链路结论，这里只追加"那份观测
    // 为什么不可靠"的归因，不修改任何 state/coverage/reason。
    // ------------------------------------------------------------
    {
        double cpu_busy = 0.0;
        bool cpu_ok = false;
        auto cpu_sample = ctx->metrics_registry->latest(
            "host:", weaknet::MetricId::CPU_BUSY_RATIO);
        if (cpu_sample) {
            cpu_ok = cpu_sample->isValid(
                weaknet::getMetricDescriptor(weaknet::MetricId::CPU_BUSY_RATIO).freshness);
            if (cpu_ok) cpu_busy = cpu_sample->value;
        }

        // DNS 是当前唯一带 observer 质量门禁的 SLE。将来其它
        // SLE 若也引入 observer 门禁，在这里并列追加即可。
        auto attr = weaknet::attributeObserverDegradation(
            dns_sle, "dns_service", cpu_busy, cpu_ok);
        if (attr.evaluated) {
            exp.observer_attribution = attr.attribution;
            exp.observer_attribution_detail = attr.explanation;
            exp.warnings.push_back(attr.explanation);
            // 归因证据挂回 SLE。
            //
            // observer_attribution.hpp 的 ObserverAttributionResult::evidence
            // 注释写的是「机器可读证据条目，直接挂到 SleResult.evidence 上」，
            // 但此前只生成不使用——Build 出来的 evidence 被整体丢弃，
            // 于是 host_cpu_busy_ratio 永远进不了任何序列化出口，
            // 诊断规则也无法用它做前置条件（buildResolver 只认 SLE evidence）。
            //
            // 挂回 exp.dns_service 而不是 dns_sle：decide() 已经按值
            // 拷贝过 SLE，改局部变量对已发布的快照没有任何影响。
            // append 而不是覆盖：observer 原有的四个比率证据必须保留。
            exp.dns_service.evidence.insert(exp.dns_service.evidence.end(),
                                            attr.evidence.begin(),
                                            attr.evidence.end());
            LOG_WARNING(LogModule::NETWORK,
                "observer attribution: " << weaknet::observerAttributionToString(attr.attribution)
                << " sle=" << attr.trigger_sle
                << " reason=" << attr.observer_reason
                << " cpu_available=" << (attr.cpu_available ? "yes" : "no")
                << " cpu_busy=" << attr.observed_cpu_busy
                << " threshold=" << attr.cpu_threshold);
        }
    }

    // ------------------------------------------------------------
    // 采集端热状态归因（同一轮评估，与上面的 observer 归因并列）
    //
    // 为什么也放在 decide() 之后：同 observer_attribution 的
    // 理由——热节流是**采集端**的物理状态，不是被观测链路的
    // 健康度。它只能解释"这份观测为什么不可靠"，不能改变
    // 链路结论。把它传进任何 evaluator 都会让同一份网络证据
    // 在板子烫与不烫时得出不同结论，同源纪律立刻失效。
    //
    // 为什么在这里采样而不是单开一个 15s 插件线程：
    // 热状态唯一的消费者就是本轮评估，采一次用一次；另开线程
    // 就得为它发明 MetricId（封闭枚举）、D-Bus 方法和配置项，
    // 那才是真正的孤儿接口。3 个 sysfs 目录的读取总耗时在
    // 百微秒量级，放在这条 15 秒一轮的线程里可以忽略。
    // ------------------------------------------------------------
    {
        const auto thermal_snapshot = thermal_reader.read();
        auto thermal = weaknet::attributeThermalState(thermal_snapshot);
        if (thermal.evaluated) {
            exp.thermal_attribution = thermal.attribution;
            exp.thermal_attribution_detail = thermal.explanation;
            exp.thermal_issues = thermal.issues;

            // 只有异常才进 warnings。NORMAL 与 UNAVAILABLE 都
            // 进 warnings 会把 warnings 变成噪音：正常态每轮都
            // 刷一条，现场会很快学会无视这个字段。
            // UNAVAILABLE 单独用 WARNING 日志记录，不进 warnings。
            if (thermal.attribution == weaknet::ThermalAttribution::THROTTLED ||
                thermal.attribution == weaknet::ThermalAttribution::FAN_ANOMALY) {
                exp.warnings.push_back(thermal.explanation);
                LOG_WARNING(LogModule::NETWORK,
                    "thermal attribution: "
                    << weaknet::thermalAttributionToString(thermal.attribution)
                    << " temp=" << thermal.max_temp_c << "C"
                    << " fan=" << (thermal.fan_present ? "yes" : "no")
                    << " duty=" << thermal.fan_duty_ratio
                    << " freq_ceiling=" << thermal.freq_ceiling_ratio
                    << " issues=" << thermal.issues.size());
            } else if (thermal.attribution == weaknet::ThermalAttribution::UNAVAILABLE) {
                LOG_WARNING(LogModule::NETWORK,
                    "thermal state unavailable; cannot rule out thermal throttling");
            }
        }
    }

    if (!rtt_samples.empty()) newest_rev = rtt_samples.back().sequence;
    else if (!reach_samples.empty()) newest_rev = reach_samples.back().sequence;
} else {
    exp.iface = active_iface;
    exp.overall = weaknet::HealthState::UNKNOWN;
    exp.display_score = 50;
}

// CR-2: 状态防抖（只有出现新 evidence 时才推进，发生稳定跃迁时发射信号）
// SR-9 单杀时传 is_critical_bypass=true，立即穿透防抖滞后
weaknet::HealthState stableState = stabilizer.update(
    exp.overall, newest_rev, std::chrono::steady_clock::now(), dns_bypass);
exp.overall = stableState;

// 采集或复用底层 L2/L3 拓扑元数据 (MAC, IP, Gateway, DNS, SSID, BSSID)
bool is_wireless_iface = (active_iface.rfind("wl", 0) == 0);

