    static std::string toExperienceJsonV2(const NetworkExperience& exp) {
        std::ostringstream json;
        json << "{\"schema_version\":2,";
        json << "\"interface\":\"" << exp.iface << "\",";
        json << "\"assessment_profile\":\"" << assessmentProfileToString(exp.assessment_profile) << "\",";
        json << "\"overall\":{";
        json << "\"state\":\"" << healthStateToString(exp.overall) << "\",";
        json << "\"coverage\":\"" << coverageToString(exp.overall_coverage) << "\",";
        json << "\"display_score\":" << exp.display_score;
        json << "},";

        auto dump_sle = [&json](const char* key, const SleResult& sle) {
            json << "\"" << key << "\":{";
            json << "\"state\":\"" << healthStateToString(sle.state) << "\",";
            json << "\"coverage\":\"" << coverageToString(sle.coverage) << "\",";
            json << "\"applicability\":\"" << applicabilityToString(sle.applicability) << "\",";
            json << "\"reason\":\"" << sle.reason << "\",";
            json << "\"evidence\":[";
            for (size_t i = 0; i < sle.evidence.size(); ++i) {
                json << "{\"metric\":\"" << sle.evidence[i].metric << "\",\"value\":" << sle.evidence[i].value << ",\"detail\":\"" << sle.evidence[i].detail << "\"}";
                if (i + 1 < sle.evidence.size()) json << ",";
            }
            json << "]}";
        };

        json << "\"network_health\":{";
        dump_sle("ip_reachability", exp.ip_reachability);
        json << ",";
        dump_sle("responsiveness", exp.responsiveness);
        json << ",";
        dump_sle("reliability", exp.reliability);
        json << ",";
        dump_sle("rf_health", exp.rf_health);
        json << "},";

        json << "\"service_health\":{";
        dump_sle("dns", exp.dns_service);
        json << ",";
        dump_sle("tcp_connect", exp.tcp_connect);
        json << ",";
        dump_sle("tcp_rtt", exp.tcp_rtt);
        json << ",";
        dump_sle("http_access", exp.http_access);
        json << ",";
        dump_sle("captive_portal", exp.captive_portal);
        json << ",";
        dump_sle("active_dns", exp.active_dns);
        json << ",";
        dump_sle("active_tcp", exp.active_tcp);
        json << ",";
        dump_sle("active_https", exp.active_https);
        json << ",";
        dump_sle("active_portal", exp.active_portal);
        json << "},";

        json << "\"warnings\":[";
        for (size_t i = 0; i < exp.warnings.size(); ++i) {
            json << "\"" << exp.warnings[i] << "\"";
            if (i + 1 < exp.warnings.size()) json << ",";
        }
        json << "],";

        // 观测者降级归因（机器可读）。
        //
        // 为什么必须进这里：该字段此前只写进 NetworkExperience，而
        // toExperienceJsonV2 是 GetNetworkExperience 的唯一出口
        // （dbus_service.cpp:923）——不序列化就等于没有任何消费者能读到，
        // 是标准的孤儿字段。归因值域是四个固定字符串，第 2 层判定
        // （observer_attribution.hpp:65-80）保证不会出现别的值。
        json << "\"observer_attribution\":\""
             << observerAttributionToString(exp.observer_attribution) << "\",";
        json << "\"observer_attribution_detail\":"
             << "\"" << exp.observer_attribution_detail << "\",";

        // 采集端热状态归因（机器可读）。
        //
        // 与 observer_attribution 同一个理由必须进这里：该字段写进
        // NetworkExperience 后，本函数是 GetNetworkExperience 的唯一出口，
        // 不序列化就是孤儿字段。两者刻意并列而非合并成一个字段——
        // "CPU 被任务占满"与"CPU 被硬件限频"是不同成因，合并会丢信息。
        json << "\"thermal_attribution\":\""
             << thermalAttributionToString(exp.thermal_attribution) << "\",";
        json << "\"thermal_attribution_detail\":"
             << "\"" << exp.thermal_attribution_detail << "\",";
        json << "\"thermal_issues\":[";
        for (size_t i = 0; i < exp.thermal_issues.size(); ++i) {
            json << "\"" << exp.thermal_issues[i] << "\"";
            if (i + 1 < exp.thermal_issues.size()) json << ",";
        }
        json << "],";

        // 视频 QoE 归因（业务侧体验）。
        //
        // 与前两个归因同一个理由必须进这里：本函数是 GetNetworkExperience
        // 的唯一出口，不序列化就是孤儿字段。三者刻意并列而**不合并**：
        //   observer_attribution → CPU 被任务占满
        //   thermal_attribution  → CPU 被硬件限频
        //   video_qoe_attribution→ 用户看到的画面卡不卡
        // 这是三个不同成因，合并会丢信息。
        //
        // 默认 NONE（无摄像头 / 未启用帧源）。NONE 不是"坏"，是"没有结论"，
        // 上层必须呈现为 unavailable，绝不能当成 healthy。
        json << "\"video_qoe_attribution\":\""
             << videoQoeAttributionToString(exp.video_qoe_attribution) << "\",";
        json << "\"video_qoe_attribution_detail\":"
             << "\"" << exp.video_qoe_attribution_detail << "\",";
        json << "\"video_qoe_issues\":[";
        for (size_t i = 0; i < exp.video_qoe_issues.size(); ++i) {
            json << "\"" << exp.video_qoe_issues[i] << "\"";
            if (i + 1 < exp.video_qoe_issues.size()) json << ",";
        }
        json << "],";

        json << "\"primary_issue\":" << (exp.primary_issue.has_value() ? ("\"" + exp.primary_issue.value() + "\"") : "null");
        json << "}";
        return json.str();
    }
};

